final class SupplementariesRuntime {
 static final BlockPos BASE=BuilderMasterInteriorRuntime.BASE,CENTER=BuilderMasterInteriorRuntime.CENTER,SACK=BASE.offset(6,1,9),BOARD=BASE.offset(1,2,6),SCONCE=BASE.offset(1,3,8),ROPE=BASE.offset(6,3,3);
 static void run(GameTestHelper h,ServerPlayer p)throws Exception{
  var level=p.serverLevel();var server=p.server;var store=CommerceService.store(server);h.assertTrue(SupplementariesInspection.supported(),"Actual exact Supplementaries4.0.2/Moonlight3.7.2 plus retained VisualWorkbench native dependencies boot");var track=store.professions(p.getUUID()).track(Profession.BUILDER);
  if(track.completedQuestIds().contains(SupplementariesInspection.QUEST)){server.tickRateManager().setTickRate(20);h.assertTrue(track.xp()==3600&&track.completedQuestIds().size()==20&&SupplementariesInspection.validate(p,CENTER).startsWith("fittings=4")&&((Container)level.getBlockEntity(SACK)).getItem(0).is(Items.STONE)&&((Container)level.getBlockEntity(SACK)).getItem(0).getCount()==8,"Actual second JVM restores all4working native fittings/storage/notice/lighting/rope,3600earnedXP/original records");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("SUPPLEMENTARIES_RESTART_PASSED: real native sack8stored items/notice text/lit sconce/anchored climbable rope and original two-floor frame persist,20earned3600XP/current canonical audit/receipt/original workshop-NPC unchanged");h.succeed();return;}
  h.assertTrue(track.xp()==3300&&track.completedQuestIds().size()==19,"Actual retained all16plus3Master objectives, no rank/quest injection");boolean refused=false;try{SupplementariesInspection.validate(p,CENTER);}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"Unfurnished room cannot satisfy native optional fittings");
  BuilderMasterInteriorRuntime.place(h,p,SACK,CreateCraftRuntime.item("supplementaries:sack"));placeOn(h,p,BOARD,"supplementaries:notice_board",BOARD.west(),Direction.EAST);placeOn(h,p,SCONCE,"supplementaries:sconce",SCONCE.west(),Direction.EAST);placeOn(h,p,ROPE,"supplementaries:rope",ROPE.above(),Direction.DOWN);placeOn(h,p,ROPE.below(),"supplementaries:rope",ROPE,Direction.DOWN);
  BlacksmithRepairRuntime.near(p,ROPE.below());p.moveTo(ROPE.getX()+.5,ROPE.getY()-1,ROPE.getZ()+.5);h.assertTrue(p.onClimbable(),"Actual native player climbability recognizes the anchored real rope");
  BlacksmithRepairRuntime.near(p,SACK);var held=p.getMainHandItem().copy();p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);use(p,SACK,Direction.UP);var menu=p.containerMenu;h.assertTrue(menu!=p.inventoryMenu&&level.getBlockEntity(SACK) instanceof Container,"Real Supplementaries sack opens its native server container");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.STONE,8));menu.quickMoveStack(p,menu.slots.size()-9+p.getInventory().selected);h.assertTrue(p.getMainHandItem().isEmpty()&&((Container)level.getBlockEntity(SACK)).getItem(0).is(Items.STONE)&&((Container)level.getBlockEntity(SACK)).getItem(0).getCount()==8,"Actual native quick-move transfers precisely8supplied items into the working sack without duplication");p.closeContainer();p.setItemInHand(InteractionHand.MAIN_HAND,held);notice(h,p,"Keep every stair and public approach clear. Return borrowed tools to their labelled storage.");
  var admin=ClaimRuntimeTests.vanillaPlayer(level,UUID.nameUUIDFromBytes("MasterInteriorInspector".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"InteriorWarden");server.getPlayerList().op(admin.getGameProfile());BuilderMasterInteriorRuntime.attend(p,admin);
  h.runAfterDelay(30,()->{try{
   h.assertTrue(SupplementariesInspection.validate(p,CENTER).startsWith("fittings=4")&&LayeredInteriorInspection.validate(p,CENTER).startsWith("interiorFloors=2"),"Four native working furnishing purposes preserve the genuine connected2floor/8zone room");String reason="Inspected authored working sack notice lighting rope with safe access and claim consent";var review=ProfessionInspectionService.review(admin,p,SupplementariesInspection.QUEST,CENTER,reason);
   BlacksmithRepairRuntime.near(p,BOARD);p.setShiftKeyDown(true);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);use(p,BOARD,Direction.EAST);p.setShiftKeyDown(false);h.assertTrue(((Container)level.getBlockEntity(BOARD)).getItem(0).isEmpty(),"Actual native crouch interaction removes the physical displayed book");notice(h,p,"Updated workshop notice: keep the emergency access clear and label all shared supply sacks.");BuilderMasterInteriorRuntime.attend(p,admin);boolean denied=false;try{ProfessionInspectionService.confirm(admin,review);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied&&store.professions(p.getUUID()).track(Profession.BUILDER).xp()==3300,"Changed still-readable native notice content invalidates reviewed evidence without XP");
   review=ProfessionInspectionService.review(admin,p,SupplementariesInspection.QUEST,CENTER,reason);ClaimRuntimeTests.opacUnclaim(level,CENTER);ClaimRuntimeTests.opacClaim(level,admin.getUUID(),CENTER);denied=false;try{ProfessionInspectionService.confirm(admin,review);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Actual post-review OPAC revocation blocks optional furnishings assessment despite operator permissions");ClaimRuntimeTests.opacUnclaim(level,CENTER);ClaimRuntimeTests.opacClaim(level,p.getUUID(),CENTER);BuilderMasterInteriorRuntime.attend(p,admin);review=ProfessionInspectionService.review(admin,p,SupplementariesInspection.QUEST,CENTER,reason);ProfessionInspectionService.confirm(admin,review);h.assertTrue(store.professions(p.getUUID()).track(Profession.BUILDER).xp()==3600&&store.professions(p.getUUID()).track(Profession.BUILDER).completedQuestIds().size()==20,"Four native fittings earn300XPonce with original19proofs retained; incomplete Master trials remain gated");CommerceService.verifyReceipt(p);h.assertTrue(EconomyStore.open(server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data")).professions(p.getUUID()).equals(store.professions(p.getUUID())),"Canonical new fitting audit and original records reopen exactly");server.getPlayerList().deop(admin.getGameProfile());com.mojang.logging.LogUtils.getLogger().info("SUPPLEMENTARIES_NATIVE_PASSED: exact registered S4recipes, native actual sack/board/lit sconce/two-rope placement/material debit, real storage quick-move/physical notice insertion-removal-replacement/native climbability, changed-text and current OPAC refusal, actual OP2assessment/3600XP/original player-built room/workshop-NPC; private furnishing/raw text supplies only");h.succeed();
  }catch(Exception e){h.fail("Native Supplementaries assessment: "+e);}});
 }
 static void notice(GameTestHelper h,ServerPlayer p,String text){BlacksmithRepairRuntime.near(p,BOARD);p.setShiftKeyDown(false);p.setItemInHand(InteractionHand.MAIN_HAND,LibraryFieldGuideRuntime.book(p,text));use(p,BOARD,Direction.EAST);h.assertTrue(p.getMainHandItem().isEmpty()&&((Container)p.serverLevel().getBlockEntity(BOARD)).getItem(0).has(DataComponents.WRITTEN_BOOK_CONTENT),"Actual native notice-board interaction consumes one physical book into the display");}
 static void use(ServerPlayer p,BlockPos pos,Direction face){if(pos.equals(BOARD)){var state=p.serverLevel().getBlockState(pos);for(var property:state.getProperties())if(property.getName().equals("facing")){var value=state.getValue(property);if(value instanceof Direction direction)face=direction;}}p.gameMode.useItemOn(p,p.serverLevel(),p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos).add(Vec3.atLowerCornerOf(face.getNormal()).scale(.5)),face,pos,false));}
 static void placeOn(GameTestHelper h,ServerPlayer p,BlockPos pos,String id,BlockPos support,Direction face){var item=CreateCraftRuntime.item(id);var held=p.getMainHandItem().copy();BlacksmithRepairRuntime.near(p,pos);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(item));use(p,support,face);h.assertTrue(p.getMainHandItem().isEmpty()&&p.serverLevel().getBlockState(pos).getBlock().asItem()==item,"Actual native supported optional fitting placement and debit: "+id+" at "+pos);p.setItemInHand(InteractionHand.MAIN_HAND,held);}
}
